const DiscCtx = createContext(paletas[0].disc);
export const useDisc = () => useContext(DiscCtx);

// Estilos partilhados pelas páginas
export const btn = 'rounded-lg border px-4 py-1.5 text-sm font-medium transition';
export const ativo = 'border-(--accent) bg-(--accent) text-(--accent-fg)';
export const inativo = 'border-(--line) bg-white text-(--ink) hover:bg-(--soft)';
export const card = 'bg-white border-r border-(--line) last:border-r-0';
export const tint = (cor: string, pct = 16) => `color-mix(in srgb, ${cor} ${pct}%, white)`;

const nav = [
  { nome: 'Horário', href: '/' },
  { nome: 'Alunos', href: '/alunos' },
  { nome: 'Pagamentos', href: '/pagamentos' },
  { nome: 'Mensagens', href: '/mensagens' }
];

export default function Shell({ children }: { children: React.ReactNode }) {
  const [p, setP] = useState(0);
  const [aberta, setAberta] = useState(false);
  const path = usePathname();
  const router = useRouter();
  const conteudo = useRef<HTMLDivElement>(null);
  const fantasma = useRef<HTMLDivElement>(null);

  // Tira uma "fotografia" da página atual e desvanece-a por cima da nova
  const crossfade = () => {
    const atual = conteudo.current;
    const alvo = fantasma.current;
    if (!atual || !alvo) return;
    const copia = atual.cloneNode(true) as HTMLElement;
    copia.removeAttribute('style');
    copia.style.cssText = 'position:absolute;inset:0;display:flex;background:white';
    alvo.replaceChildren(copia);
  };

  // Quando a nova página chega, a cópia da anterior desvanece enquanto a nova entra
  useEffect(() => {
    const copia = fantasma.current?.firstElementChild as HTMLElement | null;
    if (!copia) return;
    copia
      .animate(
        [
          { opacity: 1, filter: 'blur(0)', transform: 'scale(1)' },
          { opacity: 0, filter: 'blur(6px)', transform: 'scale(1.006)' }
        ],
        { duration: 380, easing: 'cubic-bezier(0.4, 0, 0.2, 1)', fill: 'forwards' }
      )
      .finished.then(() => copia.remove());
  }, [path]);
  const paleta = paletas[p];

  return (
    <DiscCtx.Provider value={paleta.disc}>
      <div
        style={paleta.vars as CSSProperties}
        className='flex h-screen bg-white text-(--ink) transition-colors'
      >
        <aside
          className={cn(
            'flex shrink-0 flex-col gap-2 overflow-hidden bg-(--rail) px-3 py-4 transition-[width] duration-300 ease-in-out',
            aberta ? 'w-52' : 'w-16'
          )}
        >
          <button
            onClick={() => setAberta((a) => !a)}
            title={aberta ? 'Recolher' : 'Expandir'}
            className='mb-2 flex items-center gap-3 text-left'
          >
            <span className='flex size-10 shrink-0 items-center justify-center rounded-full bg-(--logo-bg) font-bold text-(--logo-fg)'>
              CE
            </span>
            <span
              className={cn(
                'font-bold whitespace-nowrap text-(--dot) transition-opacity duration-200',
                aberta ? 'opacity-100 delay-150' : 'opacity-0'
              )}
            >
              Centro de Estudo
            </span>
          </button>
          {nav.map((n) => {
            const atual = path === n.href;
            return (
              <Link
                key={n.href}
                href={n.href}
                title={n.nome}
                onClick={(e) => {
                  if (atual) return e.preventDefault();
                  e.preventDefault();
                  crossfade();
                  router.push(n.href);
                }}
                className={cn(
                  'flex items-center gap-3 rounded-xl px-2 py-2 transition-colors hover:bg-white/10',
                  atual && aberta && 'bg-white/15'
                )}
              >
                <span
                  className={cn(
                    'size-6 shrink-0 rounded-full bg-(--dot) transition-opacity',
                    !atual && 'opacity-50'
                  )}
                />
                <span
                  className={cn(
                    'text-sm font-medium whitespace-nowrap text-(--dot) transition-all duration-200',
                    aberta ? 'translate-x-0 opacity-100 delay-150' : '-translate-x-2 opacity-0'
                  )}
                >
                  {n.nome}
                </span>
              </Link>
            );
          })}
          <div
            className={cn(
              'mt-auto flex gap-1 rounded-2xl bg-white p-1 shadow-md',
              aberta ? 'w-full flex-row flex-wrap' : 'w-10 flex-col'
            )}
          >
            {paletas.map((pl, i) => (
              <button
                key={pl.id}
                title={`${pl.id} · ${pl.nome}`}
                onClick={() => setP(i)}
                className={cn(
                  'size-8 shrink-0 rounded-full text-[11px] font-bold transition',
                  p === i ? 'bg-(--accent) text-(--accent-fg)' : 'hover:bg-(--soft)'
                )}
              >
                {pl.id}
              </button>
            ))}
          </div>
          <button
            onClick={() => setAberta((a) => !a)}
            title={aberta ? 'Recolher' : 'Expandir'}
            className='flex size-10 items-center justify-center rounded-xl text-lg text-(--dot) transition-colors hover:bg-white/10'
          >
            <span className={cn('transition-transform duration-300', aberta && 'rotate-180')}>»</span>
          </button>
        </aside>

        <style>{`
          @keyframes page-in {
            from { opacity: 0; filter: blur(4px); transform: scale(0.994); }
            to { opacity: 1; filter: blur(0); transform: none; }
          }
        `}</style>
        <div className='relative flex min-w-0 flex-1'>
          <div
            key={path}
            ref={conteudo}
            className='flex min-w-0 flex-1'
            style={{ animation: 'page-in 420ms cubic-bezier(0.22, 1, 0.36, 1) both' }}
          >
            {children}
          </div>
          {/* cópia da página anterior, que desvanece por cima da nova (crossfade) */}
          <div ref={fantasma} className='pointer-events-none absolute inset-0 z-10' />
        </div>

      </div>
    </DiscCtx.Provider>
  );
}

export function PageCard({
  titulo,
  acoes,
  children
}: {
  titulo: string;
  acoes?: React.ReactNode;
  children: React.ReactNode;
}) {
  return (
    <main className={cn(card, 'flex min-w-0 flex-1 flex-col overflow-hidden')}>
      <header className='flex items-center justify-between gap-3 px-6 pt-5 pb-3'>
        <h1 className='text-3xl font-extrabold'>{titulo}</h1>
        {acoes}
      </header>
      {children}
    </main>
  );
}
